  repository: REPOSITORY,
  distributionGuide: BASE + 'distribution/README.md',
  sellerGuide: BASE + 'sf30-seller-sdk/README.md',
  developerGuide: BASE + 'sf30-seller-sdk/DEVELOPER.md',
