  const selected = selection === 'auto' ? (draft.fields.length ? 'fields' : 'answers') : selection;
  requireValue(selected !== 'fields' || draft.fields.length > 0, 'This draft has no mapped issuer fields.');
  draft.handover ||= emptyHandover();
