export function receiveFinancialApplication(productAndFinanceMarkdown, manuscript) {
  need(typeof productAndFinanceMarkdown === 'string', 'Read the original product and finance companion.');
  const selected = extractFinancialApplication(manuscript);
  const companion = clean(productAndFinanceMarkdown);
  const positions = [...companion.matchAll(/^## Merchant settlement, customer billing and accountant receiving\s*$/gm)];
  need(positions.length <= 1, 'Keep one financial subsection in the original companion.');
  if (positions.length) {
    const start = positions[0].index;
    const nextLine = companion.indexOf('\n', start) + 1;
    const nextHeading = companion.slice(nextLine).search(/^#{1,2}\s/m);
    const end = nextHeading < 0 ? companion.length : nextLine + nextHeading;
    return clean(companion.slice(0, start) + selected + '\n' + companion.slice(end));
  }
  const before = companion.indexOf('## 7. Threat response and useful-outcome measurement\n');
  need(before >= 0, 'Retain the existing companion and its threat-response section.');
  return clean(companion.slice(0, before) + selected + '\n' + companion.slice(before));
}

/** Pin original product source while preserving the existing award and cohorts. */
export function attachFinancialSources(sourceIndex, {financeCommit, productAndFinanceMarkdown}) {
  need(sourceIndex?.schema === 'stellar-forge.grant-reviewer-source-index.v1' && Array.isArray(sourceIndex.sources),
    'Use the existing application source index.');
  need(typeof financeCommit === 'string' && /^[a-f0-9]{40}$/.test(financeCommit),
    'Select the full merged merchant financial product commit.');
  extractFinancialApplication(productAndFinanceMarkdown);
  const index = JSON.parse(JSON.stringify(sourceIndex));
  const selected = COMPONENTS.map(component => ({
    ...component, kind: 'maintained-product', repository: REPOSITORY,
    source_commit: financeCommit,
    url: REPOSITORY + 'blob/' + financeCommit + '/' + component.path,
    application_operation: FINANCIAL_OPERATION,
  }));
  for (const item of selected) {
    const matches = index.sources.map((value, position) => value.id === item.id ? position : -1).filter(position => position >= 0);
    need(matches.length <= 1, 'Keep one original source entry for ' + item.id + '.');
    if (matches.length) index.sources[matches[0]] = item;
    else index.sources.push(item);
  }
  index.narrative_source = {
    ...index.narrative_source,
    financial_product_commit: financeCommit,
    financial_application_operation: FINANCIAL_OPERATION,
  };
  index.financial_operations = {
    schema: 'stellar-forge.grant-financial-operations.v1',
    heading: FINANCIAL_HEADING.slice(3),
    companion_route: '/grant-data/product-and-finance.md',
    reader_section: '#defined-architecture-and-operating-behavior',
    source_commit: financeCommit,
    source_ids: selected.map(item => item.id),
    installed_selection: 'merchant-receivables-xero',
    installed_command: 'receivables-xero',
    operating_guide: REPOSITORY + 'blob/main/products/merchant-workspace/FINANCIAL_OPERATIONS.md',
    manuscript_operation: FINANCIAL_OPERATION,
    funded_work: 'Selected future customer Stellar integration and technical receiving within the original six priced packages.',
    measurement: 'Retain distinct original purchases and exact network/asset amounts; account, collection and receiving records continue their original economic identities.',
  };
  const basis = ' The merchant financial chapter applies the shipped settlement, invoice, collection and accountant foundation to the same prospective customer integration packages.';
  index.product_and_finance = {
    ...index.product_and_finance,
    basis: String(index.product_and_finance?.basis || '').replaceAll(basis, '') + basis,
  };
  return {sourceIndex: index, financialSources: selected, financialOperation: index.financial_operations};
}

import {ISSUER_ROUTES,attachGrantIssuerContext} from './grant-issuer-context.mjs';
// MIT. Add the handover to the original submission/editor asset composition.
export const HANDOVER_OPERATION='SCF-SUBMISSION-HANDOVER-1B40-20261012';
export const HANDOVER_ROUTES=[
  ...ISSUER_ROUTES,
  ['/grant-handover-core.mjs',['grant-handover-core.mjs','text/javascript; charset=utf-8']],
  ['/grant-handover-source.mjs',['grant-handover-source.mjs','text/javascript; charset=utf-8']],
  ['/grant-handover-workspace.mjs',['grant-handover-workspace.mjs','text/javascript; charset=utf-8']],
];
export function attachGrantHandover(sourceIndex) {
  if(sourceIndex?.schema!=='stellar-forge.grant-reviewer-source-index.v1'||
    sourceIndex.submission_workspace?.draft_schema!=='stellar-forge.grant-submission-draft.v1')
    throw new Error('Attach handover to the complete original submission workspace.');
  const result=JSON.parse(JSON.stringify(sourceIndex));
  result.submission_workspace.handover={
    schema:'stellar-forge.grant-submission-handover.v1',
    prepared_schema:'stellar-forge.grant-prepared-submission.v1',
    source_bundle_schema:'stellar-forge.grant-reviewer-source-bundle.v1',
    observation_schema:'stellar-forge.grant-submission-return.v1',
    route:'/grant-submission.html',view:'handover',
    operation:HANDOVER_OPERATION,
    export_schema:'stellar-forge.grant-submission-export.v1',
    original_files:['/grant-data/application.md','/grant-data/source-index.json','/grant-data/budget.csv','/grant-data/product-and-finance.md'],
    guide:'https://github.com/woahwhattheheck/tjlabs-stellar-merchant-workspace/blob/main/stellar-forge/developer-site/GRANT_HANDOVER.md',
    meaning:'Exact source/evidence, prepared output and operator-recorded issuer observations inside the original editable draft. No automatic issuer action.',
  };
  return attachGrantIssuerContext(result);
}
export function registerGrantHandoverAssets(manifest) {
  if(manifest?.schema!=='stellar-forge.browser-assets.v1'||!Array.isArray(manifest.routes))
    throw new Error('Use the original complete browser asset declaration.');
  const result=JSON.parse(JSON.stringify(manifest));
  for(const [route,entry]of HANDOVER_ROUTES) {
    const current=result.routes.find(row=>row[0]===route);
    if(current&&JSON.stringify(current[1])!==JSON.stringify(entry))
      throw new Error('Reconcile the current selected source for '+route+'.');
    if(!current)result.routes.push([route,entry]);
  }
  result.routes.sort((a,b)=>a[0].localeCompare(b[0]));return result;
}

// MIT. Compose complete issuer receiving into the original application and exporter.
import {stageIssuerProgramme,retainIssuerProgramme,receiveIssuerPlanning} from './dist/grant-issuer-source.mjs';
export const ISSUER_OPERATION='SCF-ISSUER-PREPARED-APPLICATION-94FE-20261013';
export const ISSUER_PROFILE_SCHEMA='stellar-forge.grant-issuer-receiving-profile.v1';
export const ISSUER_ROUTES=[
  ['/grant-issuer-core.mjs',['grant-issuer-core.mjs','text/javascript; charset=utf-8']],
  ['/grant-issuer-source.mjs',['grant-issuer-source.mjs','text/javascript; charset=utf-8']],
  ['/grant-issuer-workspace.mjs',['grant-issuer-workspace.mjs','text/javascript; charset=utf-8']],
];
const need=(value,message)=>{if(!value)throw new Error(message);};
export function validateIssuerReceivingProfile(profile){
  need(profile&&typeof profile==='object'&&!Array.isArray(profile),'Use a complete issuer receiving profile.');
  const keys=['schema','title','actor','note','sourceUrl','receivePlan'];
  need(Object.keys(profile).every(key=>keys.includes(key))&&profile.schema===ISSUER_PROFILE_SCHEMA,
    'Use the documented issuer receiving profile.');
  for(const key of ['title','actor','note','sourceUrl'])need(typeof profile[key]==='string','Record issuer receiving '+key+' as text.');
  need(profile.title.trim()&&profile.actor.trim(),'Name the issuer context and its recording operator.');
  need(typeof profile.receivePlan==='boolean','Choose explicitly whether to receive the original case-selected native plan.');
  return JSON.parse(JSON.stringify(profile));
}
export async function receiveIssuerContext(draft,bytes,profile,{filename='issuer-programme.zip',at=new Date().toISOString(),planningOptions={}}={}){
  const selected=validateIssuerReceivingProfile(profile);
  const staged=await stageIssuerProgramme(draft,bytes,{filename,at,planningOptions});
  Object.assign(staged.draft.handover.selection.issuerDraft,{title:selected.title,actor:selected.actor,note:selected.note,sourceUrl:selected.sourceUrl});
  const retained=await retainIssuerProgramme(staged.draft,{at,planningOptions});
  if(selected.receivePlan)retained.draft=await receiveIssuerPlanning(retained.draft,retained.context.id,{at,planningOptions});
  return {...retained,planningReceived:selected.receivePlan};
}
export function attachGrantIssuerContext(sourceIndex){
  need(sourceIndex?.schema==='stellar-forge.grant-reviewer-source-index.v1'&&sourceIndex.submission_workspace?.handover,
    'Attach issuer receiving to the original complete submission handover.');
  const result=JSON.parse(JSON.stringify(sourceIndex));
  result.submission_workspace.handover.issuer_programmes={
    schema:'stellar-forge.grant-issuer-context.v1',
    native_bundle_schema:'stellar-forge.sf47-operations.v1.bundle',
    native_terms_schema:'stellar-forge.sf47-award-terms.v1',
    native_correspondence_schema:'stellar-forge.issuer-correspondence.receiving.v1',
    route:'/grant-submission.html',view:'handover',operation:ISSUER_OPERATION,
    guide:'https://github.com/woahwhattheheck/tjlabs-stellar-merchant-workspace/blob/main/stellar-forge/developer-site/GRANT_ISSUER_CONTEXT.md',
    original_files:['operations.json','planning.zip','award-terms-selection.json','award-terms.html','award-terms.csv','sources/*'],
    selection:'Complete original Operations case, explicitly selected terms edition and native case-selected planning revision.',
    receiving:'The original editable draft retains full message sources, terms history, commissioning, prepared context and manual answer edits.',
  };
  return result;
}
export function registerGrantIssuerAssets(manifest){
  need(manifest?.schema==='stellar-forge.browser-assets.v1'&&Array.isArray(manifest.routes),'Use the original browser asset declaration.');
  const result=JSON.parse(JSON.stringify(manifest));
  for(const [route,entry]of ISSUER_ROUTES){
    const existing=result.routes.find(row=>row[0]===route);
    need(!existing||JSON.stringify(existing[1])===JSON.stringify(entry),'Reconcile the current issuer route '+route+'.');
    if(!existing)result.routes.push([route,entry]);
  }
  result.routes.sort((a,b)=>a[0].localeCompare(b[0]));return result;
}

