      response.end(request.method === 'HEAD' ? undefined : bytes);
    };
    if (!['127.0.0.1:' + actualPort, 'localhost:' + actualPort].includes(request.headers.host ?? ''))
      return reply(421, 'Use the original local setup address printed by this listener.');
    if (!['GET', 'HEAD'].includes(request.method))
      return reply(405, 'The setup listener serves original source files.', { Allow: 'GET, HEAD' });
    let path;
    try {
      const url = new URL(request.url, 'http://127.0.0.1:' + actualPort);
      if (url.origin !== 'http://127.0.0.1:' + actualPort) return reply(400, 'Use a local asset path.');
      path = url.pathname;
    } catch { return reply(400, 'Invalid local asset path.'); }
    const asset = assets.get(path);
    if (!asset) return reply(404, 'This path is outside the declared setup source.');
    try {
      const bytes = await readFile(asset.url);
      response.writeHead(200, { ...base, 'Content-Type': asset.type, 'Content-Length': bytes.length });
      response.end(request.method === 'HEAD' ? undefined : bytes);
    } catch (error) {
      if (response.headersSent) { response.destroy(error); return; }
      reply(error.code === 'ENOENT' ? 404 : 500,
        error.code === 'ENOENT' ? 'The selected source asset is missing. Reopen the complete installed package.'
          : 'The selected source asset could not be read.');
    }
  });
  server.requestTimeout = 30000;
  server.headersTimeout = 15000;
  await new Promise((accept, reject) => {
    server.once('error', reject);
    server.listen(port, '127.0.0.1', () => {
      server.off('error', reject);
      actualPort = server.address().port;
      accept();
    });
  });
  let stopping;
  const stop = () => stopping ??= new Promise((accept, reject) => {
    server.close(error => error ? reject(error) : accept());
    server.closeIdleConnections?.();
  });
  return {
    server, stop, url: 'http://127.0.0.1:' + actualPort + entry,
    port: actualPort, entry, assets: assets.size,
  };
}

export async function main(argv = process.argv.slice(2)) {
  if (argv.length === 1 && ['--help', '-h', 'help'].includes(argv[0])) {
    console.log(help); return;
  }
  const args = [...argv];
  if (args[0] === 'serve') args.shift();
  let port = 8787;
  if (args.length) {
    if (args.length !== 2 || args[0] !== '--port')
      throw new TypeError('Use starforge cocart-setup [serve] [--port PORT].');
    port = selectedPort(args[1]);
  }
  const listener = await startSetupServer({ port });
  const close = () => listener.stop().catch(error => {
    console.error(JSON.stringify({ error: error.code ?? error.name, message: error.message }));
    process.exitCode = 1;
  });
  process.once('SIGINT', close);
  process.once('SIGTERM', close);
  listener.server.once('close', () => {
    process.off('SIGINT', close);
    process.off('SIGTERM', close);
  });
  console.log(JSON.stringify({
    schema: 'stellar-forge.cocart-setup-listener.v1',
    url: listener.url, host: '127.0.0.1', port: listener.port,
    source: 'stellar-forge/developer-site/dist/cocart.html',
    assetManifest: 'stellar-forge/developer-site/browser-assets.json',
    assets: listener.assets,
  }));
  return listener;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  main().catch(error => {
    console.error(JSON.stringify({ error: error.code ?? error.name, message: error.message }));
    process.exitCode = 1;
  });

/**
 * Stellar Forge SF-28 - x402 Bazaar route and resource identity.
 * Pure, dependency-free catalog-ingestion guard, not a payment verifier.
 * Baseline: x402-foundation/x402@7f2b2f1f77fa5317615735e3378a6fad41cccb4e
 * specs/extensions/bazaar.md blob 442708e76d5a129e0c1393471d8ed71e3604c94e.
 * Upstream already fixes multi-encoded traversal (TS #3213, Go #3441).
 */
const RAW_TEMPLATE = /^\/[A-Za-z0-9_/:.\-~%]+$/;
const DECODED_TEMPLATE = /^\/[A-Za-z0-9_/:.\-~]+$/;
const PARAM = /^:([A-Za-z_][A-Za-z0-9_]*)$/;
const METHODS = new Set(['GET','HEAD','DELETE','POST','PUT','PATCH']);
const fail = reason => ({ok:false,reason});

/** Align five bounded decoding passes with the pinned TS/Go source. */
function fixedDecode(raw) {
  let value = raw;
  for (let pass=0; pass<5; pass++) {
    let next;
    try { next=decodeURIComponent(value); }
    catch { return fail('INVALID_PERCENT_ENCODING'); }
    if(next === value) return {ok:true,value};
    value=next;
  }
  return fail('ENCODING_DEPTH_EXCEEDED');
}

/** Stricter catalog key policy layered after the canonical SDK validator. */
export function inspectRouteTemplate(value) {
  if(typeof value!=='string'||!value) return fail('TEMPLATE_MISSING');
  if(value.length>2048) return fail('TEMPLATE_TOO_LONG');
  if(!value.startsWith('/')) return fail('TEMPLATE_NOT_ABSOLUTE');
  if(!RAW_TEMPLATE.test(value)) return fail('TEMPLATE_UNSAFE_CHAR');
  const decoded=fixedDecode(value);
  if(!decoded.ok) return fail('TEMPLATE_'+decoded.reason);
  const path=decoded.value;
  if(path.includes('..')) return fail('TEMPLATE_TRAVERSAL');
  if(path.includes('://')) return fail('TEMPLATE_SCHEME_INJECTION');
  if(!DECODED_TEMPLATE.test(path)) return fail('TEMPLATE_DECODED_UNSAFE_CHAR');
  if(value.split('/').length!==path.split('/').length) return fail('TEMPLATE_ENCODED_SEPARATOR');
  const names=new Set();
  for(const part of path.slice(1).split('/')) {
    if(!part||part==='.') return fail('TEMPLATE_AMBIGUOUS_SEGMENT');
    if(!part.includes(':')) continue;
    const match=PARAM.exec(part);
    if(!match) return fail('TEMPLATE_PARAM_SYNTAX');
    if(names.has(match[1])) return fail('TEMPLATE_DUPLICATE_PARAM');
    names.add(match[1]);
  }
  return {ok:true,canonicalPath:path,paramNames:[...names]};
}

/** Inspect the original URL before WHATWG URL can normalize away dot segments. */
export function inspectResourceURL(input) {
  if(typeof input!=='string'||!input) return fail('RESOURCE_URL_MISSING');
  if(input.length>4096) return fail('RESOURCE_URL_TOO_LONG');
  if(/[\x00-\x20\x7f\\]/.test(input)) return fail('RESOURCE_URL_UNSAFE_CHAR');
  const prefix=/^https?:\/\/([^/?#]*)/i.exec(input);
  if(!prefix) return fail('RESOURCE_URL_SCHEME');
  if(prefix[1].includes('@')) return fail('RESOURCE_URL_USERINFO');
  if(input.includes('#')) return fail('RESOURCE_URL_FRAGMENT');
  const rawPath=input.slice(prefix[0].length).split(/[?#]/,1)[0]||'/';
  if(!rawPath.startsWith('/')) return fail('RESOURCE_PATH_NOT_ABSOLUTE');
  for(const segment of rawPath.split('/')) {
    if(!segment) continue;
    let value=segment;
    for(let pass=0;pass<5;pass++) {
      let next;
      try { next=decodeURIComponent(value); }
      catch { return fail('RESOURCE_PATH_PERCENT_ENCODING'); }
      if(next==='.'||next==='..') return fail('RESOURCE_PATH_DOT_SEGMENT');
      if(next.includes('/')||next.includes('\\')) return fail('RESOURCE_PATH_ENCODED_SEPARATOR');
      if(next===value) break;
      value=next;
      if(pass===4) return fail('RESOURCE_PATH_ENCODING_DEPTH');
    }
  }
  let url;
  try { url=new URL(input); } catch { return fail('RESOURCE_URL_INVALID'); }
  if(!['http:','https:'].includes(url.protocol)) return fail('RESOURCE_URL_SCHEME');
  if(!url.hostname) return fail('RESOURCE_URL_HOST');
  if(url.username||url.password) return fail('RESOURCE_URL_USERINFO');
  return {ok:true,canonicalURL:url.href,url};
}

/** Bind a real resource path and optional echoed parameter claims to a template. */
function bindPath(template, actual, claimed) {
  const parts=template.split('/'), values=actual.split('/');
  if(parts.length!==values.length) return fail('TEMPLATE_PATH_MISMATCH');
  const bindings={};
  for(let i=1;i<parts.length;i++) {
    let value;
    try { value=decodeURIComponent(values[i]); }
    catch { return fail('RESOURCE_PATH_PERCENT_ENCODING'); }
    if(value.includes('/')||value.includes('\\')||value==='.'||value==='..') {
      return fail('RESOURCE_PATH_ENCODED_SEPARATOR');
    }
    const p=PARAM.exec(parts[i]);
    if(p) {
      if(!value) return fail('TEMPLATE_EMPTY_PARAM');
      Object.defineProperty(bindings,p[1],{value,enumerable:true,writable:true,configurable:true});
    } else if(value!==parts[i]) {
      return fail('TEMPLATE_PATH_MISMATCH');
    }
  }
  if(claimed!==undefined) {
    if(claimed===null||Array.isArray(claimed)||typeof claimed!=='object') {
      return fail('TEMPLATE_PARAMS_INVALID');
    }
    const want=Object.keys(bindings).sort(),got=Object.keys(claimed).sort();
    if(JSON.stringify(want)!==JSON.stringify(got)) return fail('TEMPLATE_PARAMS_MISMATCH');
    for(const key of want) if(String(claimed[key])!==bindings[key]) {
      return fail('TEMPLATE_PARAMS_MISMATCH');
    }
  }
  return {ok:true,bindings};
}

/**
 * Input: {resourceURL, input:{type:'http',method,pathParams?} or
 * input:{type:'mcp',toolName}, routeTemplate?}.
 * Outputs an implementation-private catalogKey, NOT authentication.
 * Independently verify seller, payTo, schema, settlement before any write.
 */
export function resolveCatalogIdentity(record) {
  if(!record||typeof record!=='object') return {status:'rejected',reason:'RECORD_INVALID'};
  const resource=inspectResourceURL(record.resourceURL);
  if(!resource.ok) return {status:'rejected',reason:resource.reason};
  if(!record.input||typeof record.input!=='object') return {status:'rejected',reason:'INPUT_MISSING'};
  const {canonicalURL,url}=resource;
  if(record.input.type==='mcp') {
    const name=record.input.toolName;
    if(typeof name!=='string'||!/^[A-Za-z0-9_.\-]{1,128}$/.test(name)) {
      return {status:'rejected',reason:'MCP_TOOL_NAME_INVALID'};
    }
    return {status:'accepted',kind:'mcp',resourceURL:canonicalURL,
      catalogKey:'mcp|'+canonicalURL+'|'+name,toolName:name};
  }
  if(record.input.type!=='http'||!METHODS.has(record.input.method)) {
    return {status:'rejected',reason:'HTTP_METHOD_INVALID'};
  }
  const method=record.input.method;
  const concrete={status:'accepted',kind:'http',resourceURL:canonicalURL,
    catalogKey:'http|'+method+'|'+canonicalURL,method};
  if(record.routeTemplate===undefined||record.routeTemplate===null) return concrete;
  const template=inspectRouteTemplate(record.routeTemplate);
  if(!template.ok) return {...concrete,status:'fallback',reason:template.reason};
  const matched=bindPath(template.canonicalPath,url.pathname,record.input.pathParams);
  if(!matched.ok) return {...concrete,status:'fallback',reason:matched.reason};
  const keyURL=url.origin+template.canonicalPath;
  return {status:'accepted',kind:'http',resourceURL:keyURL,
    catalogKey:'http|'+method+'|'+keyURL,method,
    canonicalRouteTemplate:template.canonicalPath,pathParams:matched.bindings};
}

// MIT. One static asset contract for the maintained HTTP server and source archive.
import { readFile } from 'node:fs/promises';
import { posix } from 'node:path';

const ORIGIN = 'https://starforge.invalid';
const SCHEMA = 'stellar-forge.browser-assets.v1';

function relativeFile(value, label) {
  if (typeof value !== 'string' || !value || value.startsWith('/') ||
      /[\u0000-\u0020\u007f\\?#%:]/.test(value))
    throw new TypeError('Invalid browser asset ' + label);
  return value;
}

function repositoryFile(value, label) {
  relativeFile(value, label);
  if (posix.normalize(value) !== value || value === '..' || value.startsWith('../'))
    throw new TypeError('Browser asset leaves its repository: ' + label);
  return value;
}

export function parseBrowserAssets(input) {
  const spec = JSON.parse(input);
  if (!spec || spec.schema !== SCHEMA || !Array.isArray(spec.routes) || !spec.routes.length)
    throw new TypeError('Unsupported browser asset manifest');
  relativeFile(spec.root, 'root');
  if (!spec.root.endsWith('/')) throw new TypeError('Browser asset root must be a directory');
  const paths = new Set();
  const routes = spec.routes.map(entry => {
    if (!Array.isArray(entry) || entry.length !== 2 || !Array.isArray(entry[1]) || entry[1].length !== 2)
      throw new TypeError('Browser asset route must contain a path, file and content type');
    const [path, [file, type]] = entry;
    if (typeof path !== 'string' || !path.startsWith('/') || path.startsWith('//') ||
        /[\u0000-\u0020\u007f\\?#%]/.test(path) ||
        new URL(path, ORIGIN).pathname !== path || paths.has(path))
      throw new TypeError('Invalid or duplicate browser asset route: ' + path);
    relativeFile(file, 'file');
    if (file.endsWith('/') || typeof type !== 'string' || !type || /[\r\n\u0000]/.test(type))
      throw new TypeError('Invalid browser asset file or content type: ' + path);
    paths.add(path);
    return [path, { file, type }];
  });
  return { root: spec.root, routes };
}

export async function readBrowserAssets(manifestUrl) {
  const url = new URL(manifestUrl);
  if (url.protocol !== 'file:' || url.search || url.hash)
    throw new TypeError('Browser assets require a local manifest URL');
  const spec = parseBrowserAssets(await readFile(url, 'utf8'));
  const root = new URL(spec.root, url);
  return new Map(spec.routes.map(([path, { file, type }]) =>
    [path, { url: new URL(file, root), type }]));
}

// readSource must return bytes from the same immutable source selection. Server,
// manifest and every mapped file remain ordinary, separately hashed source files.
export function createBrowserAssetIndex(registrations, readSource) {
  if (!Array.isArray(registrations) || typeof readSource !== 'function')
    throw new TypeError('Browser assets require registrations and a source reader');
  const servers = new Set(), files = new Set(), contexts = new Map();
  for (const registration of registrations) {
    if (!registration || typeof registration !== 'object' || Array.isArray(registration))
      throw new TypeError('Invalid browser asset registration');
    const server = repositoryFile(registration.server, 'server');
    const manifest = repositoryFile(registration.manifest, 'manifest');
    if (servers.has(server)) throw new TypeError('Duplicate browser asset server: ' + server);
    servers.add(server);
    readSource(server);
    const spec = parseBrowserAssets(readSource(manifest));
    const routes = new Map(spec.routes.map(([path, { file }]) =>
      [path, repositoryFile(posix.join(posix.dirname(manifest), spec.root, file), manifest + ' -> ' + file)]));
    for (const [route, file] of routes) {
      files.add(file);
      const entries = contexts.get(file) ?? [];
      entries.push({ server, manifest, route, routes });
      contexts.set(file, entries);
    }
  }
  return {
    files: [...files],
    resolve(importer, request) {
      const entries = contexts.get(importer);
      if (!entries || !request.startsWith('.') && !request.startsWith('/')) return null;
      const targets = new Set();
      for (const { server, manifest, route, routes } of entries) {
        const url = new URL(request, new URL(route, ORIGIN));
        const target = url.origin === ORIGIN && !url.search ? routes.get(url.pathname) : undefined;
        if (!target)
          throw new TypeError('Unserved browser module: ' + importer + ' -> ' + request +
            ' at ' + route + ' (' + server + '; ' + manifest + ')');
        targets.add(target);
      }
      return [...targets];
    },
  };
}

// MIT. Deterministic catalog projection shared by Node and the browser.
export const CATALOG_SCHEMA = 'stellar-forge.operator-discovery.v1';
export const SEARCH_SCHEMA = 'stellar-forge.operator-discovery-search.v1';
export const KINDS = Object.freeze(['command', 'source', 'feature', 'export', 'application', 'merchant']);
const sorted = values => [...new Set(values)].sort((a, b) => a.localeCompare(b, 'en'));
const clone = value => JSON.parse(JSON.stringify(value));
const normalized = value => String(value ?? '').normalize('NFKC').toLocaleLowerCase('en');
const flat = value => typeof value === 'string' ? value :
  Array.isArray(value) ? value.map(flat).join(' ') :
  value && typeof value === 'object' ? Object.entries(value).map(([key, item]) => key + ' ' + flat(item)).join(' ') : '';
const fail = message => { throw new TypeError(message); };

/** Project the effective maintained specification; provider modules are never evaluated. */
export function buildCommandCatalog(distribution, { featurePackages = {}, capturedAt = null } = {}) {
  const { spec, origins, sources } = distribution;
  if (!spec?.commands || !origins?.commands || !Array.isArray(sources))
    fail('Expected the maintained distribution specification and source ownership.');
  const byPath = new Map(sources.map(source => [source.path, source]));
  const owners = (field, name) => sorted((origins[field]?.[name] ?? []).map(path => byPath.get(path)?.id).filter(Boolean));
  const sourceById = new Map(sources.map(source => [source.id, source]));
  const runtimeNames = sorted([...Object.keys(spec.featurePeers ?? {}), ...Object.keys(spec.runtimePackageManifests ?? {})]);
  const features = runtimeNames.map(name => {
    const packagePath = spec.runtimePackageManifests?.[name] ?? null;
    const packageData = featurePackages[name];
    const direct = spec.featurePeers?.[name] ?? {};
    const manifestOwners = owners('runtimePackageManifests', name);
    const directOwners = sorted(Object.values(origins.featurePeers?.[name] ?? {}).flat().map(path => byPath.get(path)?.id).filter(Boolean));
    const definitions = packageData?.dependencies
      ? Object.fromEntries(Object.entries(packageData.dependencies).map(([dependency, version]) =>
        [dependency, { version, probe: direct[dependency]?.probe ?? dependency }]))
      : direct;
    return {
      id: 'feature:' + name, kind: 'feature', name,
      description: 'Declared runtime group ' + name,
      sourceIds: sorted([...manifestOwners, ...directOwners]), featureIds: [name],
      packagePath, packageRead: packagePath ? packageData?.error ? 'unavailable' : packageData?.dependencies ? 'read' : 'not-read' : 'direct',
      dependencies: Object.entries(definitions).sort(([a], [b]) => a.localeCompare(b, 'en'))
        .map(([dependency, definition]) => ({ name: dependency, ...clone(definition) })),
      ...(packageData?.error ? { error: packageData.error } : {}),
    };
  });
  if (Object.keys(spec.nativePeers ?? {}).length) features.unshift({
    id: 'feature:native', kind: 'feature', name: 'native',
    description: 'Declared native payment dependencies',
    sourceIds: sorted(Object.keys(spec.nativePeers).flatMap(name => owners('nativePeers', name))),
    featureIds: ['native'], packagePath: null, packageRead: 'direct',
    dependencies: Object.entries(spec.nativePeers).sort(([a], [b]) => a.localeCompare(b, 'en'))
      .map(([name, definition]) => ({ name, ...clone(definition) })),
  });
  const relatedFeatures = ids => features.filter(feature =>
    feature.sourceIds.some(id => ids.includes(id))).map(feature => feature.name);
  const summary = (description, ids, fallback) => description || ids
    .filter(id => id !== 'base').map(id => sourceById.get(id)?.description).filter(Boolean).join('; ') || fallback;
  const entries = Object.entries(spec.commands).sort(([a], [b]) => a.localeCompare(b, 'en'));
  const aliases = new Map();
  for (const [name, entry] of entries) aliases.set(entry, [...(aliases.get(entry) ?? []), name]);
  const commands = entries.map(([name, entry]) => {
    const sourceIds = owners('commands', name);
    return { id: 'command:' + name, kind: 'command', name, entry,
      description: summary(spec.commandDescriptions?.[name], sourceIds, 'Maintained merchant toolkit command'),
      sourceIds, featureIds: relatedFeatures(sourceIds), aliases: aliases.get(entry).filter(alias => alias !== name),
      helpArgv: ['starforge', name, '--help'] };
  });
  const exported = Object.entries(spec.exports ?? {}).sort(([a], [b]) => a.localeCompare(b, 'en')).map(([name, target]) => {
    const sourceIds = owners('exports', name);
    return { id: 'export:' + name, kind: 'export', name,
      description: summary(null, sourceIds, 'Declared application package export'),
      sourceIds, featureIds: relatedFeatures(sourceIds), target: clone(target) };
  });
  const providers = [['application', 'applicationProviders'], ['merchant', 'merchantProviders']].flatMap(([kind, field]) =>
    Object.entries(spec[field] ?? {}).sort(([a], [b]) => a.localeCompare(b, 'en')).map(([name, entry]) => {
      const sourceIds = owners(field, name);
      return { id: kind + ':' + name, kind, name, entry,
        description: summary(null, sourceIds, kind === 'application' ? 'Applications provider' : 'Merchant MCP provider'),
        sourceIds, featureIds: relatedFeatures(sourceIds) };
    }));
  const sourceItems = sources.map(source => {
    const sourceIds = [source.id];
    return { id: 'source:' + source.id, kind: 'source', name: source.id, path: source.path,
      description: source.description, sourceIds, featureIds: relatedFeatures(sourceIds),
      commands: commands.filter(item => item.sourceIds.includes(source.id)).map(item => item.name),
      exports: exported.filter(item => item.sourceIds.includes(source.id)).map(item => item.name),
      applications: providers.filter(item => item.kind === 'application' && item.sourceIds.includes(source.id)).map(item => item.name),
      merchantProviders: providers.filter(item => item.kind === 'merchant' && item.sourceIds.includes(source.id)).map(item => item.name),
    };
  }).sort((a, b) => a.name.localeCompare(b.name, 'en'));
  const items = [...commands, ...sourceItems, ...features, ...exported, ...providers];
  return {
    schema: CATALOG_SCHEMA,
    package: { name: spec.name, version: distribution.manifest?.packageVersion ?? 'source-checkout',
      sourceCommit: distribution.manifest?.sourceCommit ?? null,
      sourceSelection: distribution.selection ? { id: distribution.selection.id, title: distribution.selection.title } : null },
    capturedAt,
    counts: Object.fromEntries(KINDS.map(kind => [kind, items.filter(item => item.kind === kind).length])),
    sources: sourceItems.map(({ name, description, path }) => ({ id: name, description, path })),
    featureNames: features.map(item => item.name).sort(),
    items,
  };
}

export function tokenizeQuery(query = '') {
  if (typeof query !== 'string' || query.length > 512 || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(query))
    fail('Search must be text of at most 512 characters.');
  const tokens = [];
  let current = '', quoted = false;
  for (const character of query.trim()) {
    if (character === '"') { quoted = !quoted; continue; }
    if (/\s/u.test(character) && !quoted) {
      if (current) { tokens.push(normalized(current)); current = ''; }
    } else current += character;
  }
  if (quoted) fail('Close the quoted search phrase.');
  if (current) tokens.push(normalized(current));
  return sorted(tokens);
}

function select(catalog, { query = '', kind = 'all', source = '', feature = '' } = {}) {
  if (catalog?.schema !== CATALOG_SCHEMA || !Array.isArray(catalog.items))
    fail('Expected an operator command catalog.');
  if (kind !== 'all' && !KINDS.includes(kind)) fail('Unknown catalog kind: ' + kind);
  if (source && !catalog.sources.some(item => item.id === source)) fail('Unknown registration source: ' + source);
  if (feature && !catalog.featureNames.includes(feature)) fail('Unknown runtime group: ' + feature);
  const tokens = tokenizeQuery(query);
  const filtered = catalog.items.flatMap(item => {
    if (kind !== 'all' && item.kind !== kind || source && !item.sourceIds.includes(source) ||
        feature && !item.featureIds.includes(feature)) return [];
    const name = normalized(item.name), description = normalized(item.description);
    const text = normalized(flat(item));
    if (!tokens.every(token => text.includes(token))) return [];
    const score = tokens.reduce((value, token) => value +
      (name === token ? 1000 : name.startsWith(token) ? 300 : name.includes(token) ? 100 : description.includes(token) ? 20 : 1), 0);
    return [{ item, score }];
  });
  return filtered.sort((a, b) => b.score - a.score ||
    KINDS.indexOf(a.item.kind) - KINDS.indexOf(b.item.kind) || a.item.name.localeCompare(b.item.name, 'en'))
    .map(({ item }) => item);
}

function positiveInteger(value, name, maximum) {
  if (!Number.isSafeInteger(value) || value < 1 || value > maximum)
    fail(name + ' must be an integer from 1 to ' + maximum + '.');
  return value;
}

/** Filters are ANDed; complete match counts and pagination always remain explicit. */
export function searchCommandCatalog(catalog, options = {}) {
  const { query = '', kind = 'all', source = '', feature = '', page = 1, pageSize = 50 } = options;
  positiveInteger(page, 'page', Number.MAX_SAFE_INTEGER);
  positiveInteger(pageSize, 'pageSize', 500);
  const matching = select(catalog, { query, kind, source, feature });
  const pages = Math.max(1, Math.ceil(matching.length / pageSize));
  const currentPage = Math.min(page, pages);
